CREATE TABLE service_package (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL, description VARCHAR(1000) NOT NULL, cover_url VARCHAR(500), price DECIMAL(10,2) NOT NULL, duration_minutes INT NOT NULL, buffer_minutes INT NOT NULL DEFAULT 30, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(price>=0),CHECK(duration_minutes>0),CHECK(buffer_minutes>=0));
CREATE TABLE venue (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,location VARCHAR(200) NOT NULL,description VARCHAR(500) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE package_photographer(package_id BIGINT NOT NULL,employee_id BIGINT NOT NULL,PRIMARY KEY(package_id,employee_id),FOREIGN KEY(package_id) REFERENCES service_package(id),FOREIGN KEY(employee_id) REFERENCES employee(id));
CREATE TABLE package_venue(package_id BIGINT NOT NULL,venue_id BIGINT NOT NULL,PRIMARY KEY(package_id,venue_id),FOREIGN KEY(package_id) REFERENCES service_package(id),FOREIGN KEY(venue_id) REFERENCES venue(id));
CREATE TABLE photographer_schedule(id BIGINT PRIMARY KEY AUTO_INCREMENT,resource_id BIGINT NOT NULL,work_date DATE NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(resource_id,work_date),FOREIGN KEY(resource_id) REFERENCES employee(id));
CREATE TABLE photographer_schedule_period(id BIGINT PRIMARY KEY AUTO_INCREMENT,schedule_id BIGINT NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,FOREIGN KEY(schedule_id) REFERENCES photographer_schedule(id),CHECK(start_time<end_time));
CREATE TABLE venue_schedule(id BIGINT PRIMARY KEY AUTO_INCREMENT,resource_id BIGINT NOT NULL,work_date DATE NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(resource_id,work_date),FOREIGN KEY(resource_id) REFERENCES venue(id));
CREATE TABLE venue_schedule_period(id BIGINT PRIMARY KEY AUTO_INCREMENT,schedule_id BIGINT NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,FOREIGN KEY(schedule_id) REFERENCES venue_schedule(id),CHECK(start_time<end_time));
CREATE TABLE appointment (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,appointment_no VARCHAR(40) NOT NULL UNIQUE,customer_id BIGINT NOT NULL,package_id BIGINT NOT NULL,photographer_id BIGINT NOT NULL,venue_id BIGINT NOT NULL,start_time DATETIME NOT NULL,shoot_end_time DATETIME NOT NULL,occupied_end_time DATETIME NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'CONFIRMED',amount DECIMAL(10,2) NOT NULL,package_name VARCHAR(80) NOT NULL,photographer_name VARCHAR(40) NOT NULL,venue_name VARCHAR(80) NOT NULL,customer_name VARCHAR(40) NOT NULL,customer_phone VARCHAR(20) NOT NULL,duration_minutes INT NOT NULL,buffer_minutes INT NOT NULL,source VARCHAR(20) NOT NULL,remark VARCHAR(500),version INT NOT NULL DEFAULT 0,request_id VARCHAR(64) NOT NULL UNIQUE,request_fingerprint CHAR(64) NOT NULL,created_by BIGINT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(customer_id) REFERENCES customer(id),FOREIGN KEY(package_id) REFERENCES service_package(id),FOREIGN KEY(photographer_id) REFERENCES employee(id),FOREIGN KEY(venue_id) REFERENCES venue(id),FOREIGN KEY(created_by) REFERENCES sys_user(id),INDEX(photographer_id,start_time,occupied_end_time),INDEX(venue_id,start_time,occupied_end_time),INDEX(customer_id,start_time));
CREATE TABLE appointment_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,appointment_id BIGINT NOT NULL,action VARCHAR(30) NOT NULL,operator_id BIGINT NOT NULL,detail VARCHAR(1000) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointment(id));
